const body = $json.body || $json;
const pregunta = String(body.pregunta || '').trim();

if (!pregunta) throw new Error('La pregunta no puede estar vacía');

const arr = v => Array.isArray(v) ? v : (v ? [v] : []);

return {
  json: {
    id_consulta: body.id_consulta ?? body.idConsulta ?? null,
    pregunta,
    nivel_experiencia: body.nivel_experiencia || body.nivelExperiencia || 'Principiante',
    area_interes: body.area_interes || body.areaInteres || 'General',
    cursos_previos: arr(body.cursos_previos || body.cursosPrevios),
    contexto_previo: body.contexto_previo || body.contextoPrevio || '',
    umbral: Number(body.umbral ?? 0.40)
  }
};

const d = $json;
const p = d.pregunta.toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .trim();

const isAboutRutaIA = /\bruta\s*ia\b/.test(p) || /\b(esta plataforma|este asesor|esta pagina|este sistema|este chatbot|este bot)\b/.test(p);
const isIdentityQuestion = /\b(que es|quien es|como funciona|que hace|para que sirve|para que es|que funcion|cual es la funcion|que utilidad|proposito|objetivo|mision|de que trata|como me ayuda|en que me ayuda|que puedo hacer|que ofreces|que sabes hacer)\b/.test(p);

const identitySelfPatterns = [
  /\bquien eres\b/,
  /\bque eres\b/,
  /\bque puedes hacer\b/,
  /\bcomo me puedes ayudar\b/,
  /\bpara que sirves\b/,
  /\bcual es tu funcion\b/,
  /\bque funcion cumples\b/,
  /\bque funcion tienes\b/
];

const catalog = [
  /\b(cuales|que)\s+son\s+(todos\s+)?(los\s+)?cursos\b/,
  /\bque\s+cursos\s+(hay|tienen|ofrecen|estan disponibles)\b/,
  /\b(catalogo|lista)\s+(de\s+)?cursos\b/,
  /\bmu[eé]strame\s+(todos\s+)?los\s+cursos\b/,
  /\bdame\s+(todos\s+)?los\s+cursos\b/,
  /\bque\s+puedo\s+estudiar\b/,
  /\bque\s+opciones\s+de\s+formacion\s+tienen\b/
];

const outside = [
  /\b(pilotaje|avioneta|aviacion|gastronomia|cocina|medicina|derecho|odontologia|enfermeria|mecanica automotriz)\b/
];

let intent = 'search';
if ((isAboutRutaIA && isIdentityQuestion) || identitySelfPatterns.some(r => r.test(p))) intent = 'identity';
else if (catalog.some(r => r.test(p))) intent = 'catalog';
else if (outside.some(r => r.test(p))) intent = 'outside';

return { json: { ...d, intent } };

const d = $json;
return {json: {
  id_consulta: d.id_consulta,
  pregunta: d.pregunta,
  respuesta: "RutaIA es una plataforma inteligente de orientación académica y vocacional. Mi función principal es guiarte para descubrir los cursos ideales de nuestro catálogo según tus intereses, nivel actual y metas profesionales. También puedo darte información sobre las áreas de estudio disponibles, resolver tus dudas sobre la oferta formativa y ayudarte a trazar tu ruta de aprendizaje paso a paso.",
  fuentes: [],
  similitudes: [],
  estado_final: "Respondida",
  intent: "identity"
}};

