const r = $json.result || {};
const points = r.points || [];

const cursos = points.map(x => {
  const p = x.payload || {};
  return {
    id: p.curso_id || x.id,
    nombre: p.nombre || 'Sin nombre',
    categoria: p.categoria || 'Sin categoría',
    nivel: p.nivel || 'No especificado',
    duracion_horas: p.duracion_horas ?? null,
    descripcion: p.descripcion || ''
  };
});

cursos.sort((a,b) =>
  String(a.categoria).localeCompare(String(b.categoria), 'es') ||
  String(a.nombre).localeCompare(String(b.nombre), 'es')
);

const contexto = cursos.map((c,i) =>
  `${i+1}. ${c.nombre} | Categoría: ${c.categoria} | Nivel: ${c.nivel} | Duración: ${c.duracion_horas ?? 'N/D'}h | ${c.descripcion}`
).join('\n');

return {
  json: {
    id_consulta: $('Clasificar Intención').first().json.id_consulta,
    pregunta: $('Clasificar Intención').first().json.pregunta,
    respuesta: cursos.length
      ? `Estos son los cursos actualmente disponibles en el catálogo institucional:\n\n${contexto}`
      : 'Actualmente no se encontraron cursos activos en el catálogo institucional.',
    fuentes: cursos,
    similitudes: [],
    estado_final: cursos.length ? 'Respondida' : 'Sin resultados',
    intent: 'catalog'
  }
};

