const q = $('Clasificar Intención').first().json;
const results = Array.isArray($json.result) ? $json.result : [];
const threshold = Number(q.umbral ?? 0.40);

let fuentes = results
  .filter(r => Number(r.score ?? 0) >= threshold)
  .map(r => {
    const p = r.payload || {};
    return {
      id: p.curso_id || r.id,
      nombre: p.nombre || 'Sin nombre',
      descripcion: p.descripcion || '',
      categoria: p.categoria || 'Sin categoría',
      nivel: p.nivel || 'No especificado',
      duracion_horas: p.duracion_horas ?? null,
      similitud: Math.round(Number(r.score || 0) * 10000) / 10000
    };
  });

const nivel = String(q.nivel_experiencia || '').toLowerCase();
fuentes.sort((a,b) => {
  let sa = a.similitud, sb = b.similitud;
  if (/principiante|basico/.test(nivel)) {
    if (/principiante|basico/i.test(a.nivel)) sa += 0.08;
    if (/avanzado/i.test(a.nivel)) sa -= 0.08;
    if (/principiante|basico/i.test(b.nivel)) sb += 0.08;
    if (/avanzado/i.test(b.nivel)) sb -= 0.08;
  }
  return sb - sa;
});

if (!fuentes.length) {
  return {json: {
    ...q,
    fuentes: [],
    similitudes: [],
    contexto: '',
    ejecutar_llm: false,
    respuesta: `No encontré cursos suficientemente relacionados con "${q.pregunta}" dentro del catálogo institucional.`,
    estado_final: 'Sin resultados'
  }};
}

const contexto = fuentes.map((f,i) =>
`Curso ${i+1}
- Nombre exacto: ${f.nombre}
- ID: ${f.id}
- Categoría: ${f.categoria}
- Nivel: ${f.nivel}
- Duración: ${f.duracion_horas ?? 'N/D'} horas
- Similitud: ${(f.similitud*100).toFixed(2)}%
- Descripción: ${f.descripcion}`
).join('\n\n');

return {json: {
  ...q,
  fuentes,
  similitudes: fuentes.map(f=>f.similitud),
  contexto,
  ejecutar_llm: true
}};

const d = $json;
return {json: {
  id_consulta: d.id_consulta,
  pregunta: d.pregunta,
  respuesta: "RutaIA está orientada principalmente a formación en tecnología y software. Actualmente no encontré formación sobre esa temática en nuestro catálogo institucional. Puedes consultar una institución especializada en el área que buscas.",
  fuentes: [],
  similitudes: [],
  estado_final: "Fuera del catálogo",
  intent: "outside"
}};

const d = $json;
const apiKey = $env.GEMINI_API_KEY || 'AQ.Ab8RN6KZsL8-XMY422XdGnZ8r8cYeZ9ZhpS3rhD_6lMMh8G5fA';

const prompt = `Eres RutaIA Asesor, asistente de orientación vocacional y académica institucional.\n\nREGLA PRINCIPAL:\nOrienta al estudiante recomendándole el o los cursos más pertinentes de nuestro catálogo institucional. Redacta de forma cálida, cercana y motivadora, siguiendo este estilo y estructura:\n- Saluda amablemente y valida el interés del estudiante en el tema.\n- Recomienda con entusiasmo el curso más afín, destacando su nombre exacto en **negrita**, su nivel y duración en horas.\n- Explica de forma clara y pedagógica por qué este curso es ideal para él o ella, usando viñetas con motivos concretos (por ejemplo: "* **Nivel Básico y Práctico:** ...", "* **Habilidades clave:** ...").\n- Jamás escribas etiquetas frías como "Descripción:" o "Detalles del curso:". La explicación debe fluir de forma natural.\n- Si hay cursos complementarios en el contexto, menciónalos brevemente como sugerencia de ruta futura.\n\nFUENTE DE VERDAD:\nSolo usa los cursos del CONTEXTO DEL CATÁLOGO. No inventes cursos, nombres, niveles ni duraciones.\n\nPERFIL:\nNivel: ${d.nivel_experiencia || 'Principiante'}\nÁrea: ${d.area_interes || 'General'}\nCursos previos: ${(d.cursos_previos || []).join(', ') || 'Ninguno'}\nContexto previo: ${d.contexto_previo || 'Sin contexto'}\n\nPREGUNTA ACTUAL:\n${d.pregunta}\n\nCONTEXTO DEL CATÁLOGO:\n${d.contexto}\n\nGenera la orientación para el estudiante:`;

let respuestaTexto = '';
const models = ['gemini-3-flash-preview', 'gemma-4-26b-a4b-it', 'gemini-3.6-flash'];

for (const model of models) {
  try {
    const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        generationConfig: { temperature: 0.2, maxOutputTokens: 2048 }
      })
    });
    if (res.ok) {
      const data = await res.json();
      const text = data?.candidates?.[0]?.content?.parts?.[0]?.text;
      if (text && text.trim()) {
        respuestaTexto = text.trim();
        break;
      }
    }
  } catch (err) {}
}

if (!respuestaTexto && d.fuentes && d.fuentes.length > 0) {
  const top = d.fuentes[0];
  const dur = top.duracion_horas || top.duracionHoras || 40;
  respuestaTexto = `¡Hola! Qué gusto poder guiarte en tu camino hacia ${d.pregunta}. Para comenzar a dominar esta tecnología, te recomiendo encarecidamente el curso **${top.nombre}** de nuestro catálogo.\n\nEste curso es ideal para ti porque:\n* **Nivel ${top.nivel} y Enfoque Práctico:** Te proporcionará los fundamentos sólidos que necesitas, con ${dur} horas de formación.\n* **Dominio de herramientas:** ${top.descripcion}\n\n¡Estoy aquí para acompañarte en tu formación!`;
}

return {json: {
  id_consulta: d.id_consulta,
  pregunta: d.pregunta,
  respuesta: respuestaTexto || 'No encontramos cursos que coincidan con tu búsqueda en este momento.',
  fuentes: d.fuentes || [],
  similitudes: d.similitudes || [],
  estado_final: (d.fuentes && d.fuentes.length > 0) ? 'Respondida' : 'Sin resultados',
  intent: d.intent || 'search'
}};

const d = $json;
return {json: {
  id_consulta: d.id_consulta,
  pregunta: d.pregunta,
  respuesta: d.respuesta,
  fuentes: [],
  similitudes: [],
  estado_final: d.estado_final || 'Sin resultados',
  intent: d.intent || 'search'
}};
